import React, { useEffect, useRef, useState } from 'react';
import { predictProducts } from '../services/api';

const ProductSearchAutocomplete = ({ value, onChange, onSelect, placeholder = 'Search products...' }) => {
  const [suggestions, setSuggestions] = useState([]);
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [highlight, setHighlight] = useState(-1);
  const containerRef = useRef(null);

  // Debounce value
  const [debounced, setDebounced] = useState(value || '');
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value || ''), 200);
    return () => clearTimeout(t);
  }, [value]);

  useEffect(() => {
    const run = async () => {
      if (!debounced || debounced.trim().length < 2) {
        setSuggestions([]);
        setOpen(false);
        return;
      }
      setLoading(true);
      try {
        const resp = await predictProducts(debounced, 8);
        setSuggestions(resp?.data || []);
        setOpen(true);
      } catch (e) {
        setSuggestions([]);
        setOpen(false);
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [debounced]);

  useEffect(() => {
    const onClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  const handleKeyDown = (e) => {
    if (!open) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlight((h) => Math.min(h + 1, suggestions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlight((h) => Math.max(h - 1, 0));
    } else if (e.key === 'Enter') {
      if (highlight >= 0 && suggestions[highlight]) {
        onSelect?.(suggestions[highlight]);
        setOpen(false);
      }
    } else if (e.key === 'Escape') {
      setOpen(false);
    }
  };

  return (
    <div className="relative" ref={containerRef}>
      <input
        value={value}
        onChange={(e) => onChange?.(e.target.value)}
        onFocus={() => suggestions.length > 0 && setOpen(true)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        className="input pl-3 pr-10"
      />
      {loading && (
        <div className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 spinner" />
      )}
      {open && suggestions.length > 0 && (
        <div className="absolute z-50 mt-1 w-full bg-white border border-gray-200 rounded-lg shadow-lg max-h-72 overflow-auto">
          {suggestions.map((s, idx) => (
            <button
              key={s.id}
              onMouseDown={(e) => {
                e.preventDefault();
                onSelect?.(s);
                setOpen(false);
              }}
              onMouseEnter={() => setHighlight(idx)}
              className={`w-full flex items-center p-2 text-left hover:bg-gray-50 ${
                highlight === idx ? 'bg-gray-50' : ''
              }`}
            >
              {s.image ? (
                <img src={s.image} alt={s.title} className="w-10 h-10 object-cover rounded mr-2" />
              ) : (
                <div className="w-10 h-10 bg-gray-200 rounded mr-2" />)
              }
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium text-gray-900 truncate">{s.title}</div>
                <div className="text-xs text-gray-500 truncate">{s.vendor || ''}</div>
              </div>
              {s.price && (
                <div className="text-sm text-gray-700 ml-2">${parseFloat(s.price).toFixed(2)}</div>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default ProductSearchAutocomplete;
